import { useCallback, useEffect, useRef, useState } from "react";
import { Box, Download, ImagePlus, Loader2, PowerOff, RefreshCw, Sparkles } from "lucide-react";
import { Button } from "@/components/ui/button";
import { supabase } from "@/integrations/supabase/client";
import SpaceModelViewer from "./SpaceModelViewer";

/**
 * 3D Modeler — one photo in, a real 3D model (GLB) out.
 * The model is generated by TRELLIS 2 (Microsoft, MIT open source)
 * running on the founder's own PC as the platform's GPU node, through
 * the generate-3d-model edge function (sign-in + Global Credit charge).
 * When that PC is off, the engine reports offline and nothing is charged.
 */

type EngineStatus = {
  online: boolean;
  gpu: string | null;
  vramGb: number | null;
  tiers: string[];
  prices: Record<string, number>;
};

type Phase = "idle" | "queued" | "running" | "done" | "failed";

const TIER_LABEL: Record<string, string> = {
  "512": "Standard · 512",
  "1024": "High · 1024",
  "1536": "Ultra · 1536",
};

export default function Modeler3D() {
  const [checking, setChecking] = useState(true);
  const [engine, setEngine] = useState<EngineStatus | null>(null);
  const [photo, setPhoto] = useState<string | null>(null);
  const [photoName, setPhotoName] = useState("");
  const [tier, setTier] = useState<string>("512");
  const [phase, setPhase] = useState<Phase>("idle");
  const [jobId, setJobId] = useState<string | null>(null);
  const [modelUrl, setModelUrl] = useState<string | null>(null);
  const [credits, setCredits] = useState<number | null>(null);
  const [notice, setNotice] = useState<string | null>(null);
  const pollRef = useRef<ReturnType<typeof setInterval> | null>(null);

  const checkEngine = useCallback(async () => {
    setChecking(true);
    try {
      const { data } = await supabase.functions.invoke("generate-3d-model", { body: { action: "status" } });
      if (data && typeof data.online === "boolean") {
        setEngine(data as EngineStatus);
        if (data.online && Array.isArray(data.tiers) && data.tiers.length && !data.tiers.includes(tier)) {
          setTier(data.tiers[0]);
        }
      } else {
        setEngine({ online: false, gpu: null, vramGb: null, tiers: [], prices: {} });
      }
    } catch {
      setEngine({ online: false, gpu: null, vramGb: null, tiers: [], prices: {} });
    } finally {
      setChecking(false);
    }
  }, [tier]);

  useEffect(() => { checkEngine(); }, [checkEngine]);

  useEffect(() => () => { if (pollRef.current) clearInterval(pollRef.current); }, []);

  const pickPhoto = (f: File | undefined) => {
    if (!f) return;
    if (!/^image\/(png|jpeg|webp)$/.test(f.type)) { setNotice("Please choose a PNG, JPG or WebP photo."); return; }
    if (f.size > 12 * 1024 * 1024) { setNotice("That photo is over 12MB — please pick a smaller one."); return; }
    const r = new FileReader();
    r.onload = () => { setPhoto(String(r.result)); setPhotoName(f.name); setNotice(null); setPhase("idle"); setModelUrl(null); };
    r.readAsDataURL(f);
  };

  const stopPolling = () => { if (pollRef.current) { clearInterval(pollRef.current); pollRef.current = null; } };

  const poll = useCallback((id: string) => {
    stopPolling();
    pollRef.current = setInterval(async () => {
      const { data } = await supabase.functions.invoke("generate-3d-model", { body: { action: "poll", jobId: id } });
      if (!data) return;
      if (data.status === "running") setPhase("running");
      if (data.status === "done") { stopPolling(); setPhase("done"); setModelUrl(data.modelUrl); }
      if (data.status === "failed") {
        stopPolling(); setPhase("failed");
        setNotice("The model couldn't be built from that photo. Your Credits were refunded — try a clearer photo of a single object.");
      }
    }, 4000);
  }, []);

  const generate = async () => {
    if (!photo || !engine?.online) return;
    setNotice(null); setModelUrl(null); setPhase("queued");
    const { data, error } = await supabase.functions.invoke("generate-3d-model", {
      body: { action: "create", imageDataUrl: photo, tier },
    });
    const code = (data as { error?: string } | null)?.error || (error ? "failed" : "");
    if (code === "engine_offline") { setPhase("idle"); setNotice("The 3D engine just went offline — nothing was charged."); checkEngine(); return; }
    if (code === "limit_reached") { setPhase("idle"); setNotice("You're out of Global Credits. Top up or upgrade your plan to keep creating."); return; }
    if (code === "tier_unavailable") { setPhase("idle"); setNotice("That quality tier isn't available on the connected engine."); return; }
    if (!data?.jobId) { setPhase("idle"); setNotice("Something went wrong starting your model — you were not charged."); return; }
    if (typeof data.credits === "number") setCredits(data.credits);
    setJobId(data.jobId);
    poll(data.jobId);
  };

  const reset = () => { stopPolling(); setPhase("idle"); setJobId(null); setModelUrl(null); setNotice(null); };

  return (
    <div className="h-full overflow-auto p-4 sm:p-6 space-y-5">
      {/* Engine status */}
      <div className="flex items-center gap-3 flex-wrap">
        <span className={`inline-flex items-center gap-2 rounded-full border px-3 py-1 text-xs font-medium ${engine?.online ? "border-emerald-500/40 text-emerald-500" : "border-border text-muted-foreground"}`}>
          <span className={`h-2 w-2 rounded-full ${engine?.online ? "bg-emerald-500" : "bg-muted-foreground/50"}`} />
          {checking ? "Checking the 3D engine…" : engine?.online ? `Engine online · ${engine.gpu}${engine.vramGb ? ` · ${engine.vramGb}GB` : ""}` : "Engine offline"}
        </span>
        {credits !== null && <span className="text-xs text-muted-foreground">Balance: {credits} Credits</span>}
        <Button variant="ghost" size="sm" onClick={checkEngine} disabled={checking} className="h-7 px-2 text-xs">
          <RefreshCw className={`h-3.5 w-3.5 mr-1 ${checking ? "animate-spin" : ""}`} /> Check again
        </Button>
      </div>

      {!checking && engine && !engine.online && (
        <div className="rounded-xl border border-dashed p-6 text-center space-y-2">
          <PowerOff className="h-8 w-8 mx-auto text-muted-foreground" />
          <p className="font-medium">The 3D engine is offline</p>
          <p className="text-sm text-muted-foreground max-w-md mx-auto">
            Your models are made by TRELLIS 2, an open-source AI that runs on the Startup Factory
            computer — and that computer is switched off right now. Nothing is charged while it's
            offline. Check back when it's on.
          </p>
        </div>
      )}

      {engine?.online && phase !== "done" && (
        <>
          {/* Photo picker */}
          <div className="space-y-2">
            <p className="text-sm font-medium">1 · One photo of one object</p>
            <label className="flex flex-col items-center justify-center gap-2 rounded-xl border border-dashed p-6 cursor-pointer hover:bg-accent/40 transition-colors">
              {photo ? (
                <img src={photo} alt={photoName} className="max-h-48 rounded-lg object-contain" />
              ) : (
                <>
                  <ImagePlus className="h-8 w-8 text-muted-foreground" />
                  <span className="text-sm text-muted-foreground">Tap to choose a photo — a single object on a plain background works best</span>
                </>
              )}
              <input type="file" accept="image/png,image/jpeg,image/webp" className="hidden"
                onChange={(e) => { pickPhoto(e.target.files?.[0]); e.target.value = ""; }} />
            </label>
            {photo && <p className="text-xs text-muted-foreground">{photoName} — tap the photo to change it</p>}
          </div>

          {/* Tier picker */}
          <div className="space-y-2">
            <p className="text-sm font-medium">2 · Quality</p>
            <div className="grid grid-cols-3 gap-2">
              {["512", "1024", "1536"].map((t) => {
                const available = engine.tiers.includes(t);
                const active = tier === t;
                return (
                  <button key={t} disabled={!available} onClick={() => setTier(t)}
                    className={`rounded-xl border p-3 text-left transition-colors ${active ? "border-primary bg-primary/10" : "border-border"} ${available ? "hover:bg-accent/40" : "opacity-40 cursor-not-allowed"}`}>
                    <span className="block text-sm font-medium">{TIER_LABEL[t]}</span>
                    <span className="block text-xs text-muted-foreground">
                      {available ? `${engine.prices[t] ?? ""} Credits` : "Not on this engine"}
                    </span>
                  </button>
                );
              })}
            </div>
          </div>

          <Button onClick={generate} disabled={!photo || phase === "queued" || phase === "running"} className="w-full sm:w-auto">
            {phase === "queued" || phase === "running"
              ? <><Loader2 className="h-4 w-4 mr-2 animate-spin" /> {phase === "queued" ? "Waiting for the engine…" : "Building your model…"}</>
              : <><Sparkles className="h-4 w-4 mr-2" /> Create my 3D model</>}
          </Button>
          {(phase === "queued" || phase === "running") && (
            <p className="text-xs text-muted-foreground">
              The engine builds your model on the Startup Factory computer — this can take a few
              minutes. You can leave this open; the model appears here when it's ready.
            </p>
          )}
        </>
      )}

      {notice && <p className="rounded-lg border border-amber-500/40 bg-amber-500/10 px-3 py-2 text-sm">{notice}</p>}

      {phase === "done" && modelUrl && (
        <div className="space-y-3">
          <p className="text-sm font-medium flex items-center gap-2"><Box className="h-4 w-4" /> Your 3D model</p>
          <div className="rounded-xl border overflow-hidden">
            <SpaceModelViewer models={[{ name: "Your 3D model", src: modelUrl, alt: "Your generated 3D model" }]} />
          </div>
          <div className="flex gap-2 flex-wrap">
            <Button asChild><a href={modelUrl} download="my-3d-model.glb"><Download className="h-4 w-4 mr-2" /> Download GLB</a></Button>
            <Button variant="outline" onClick={reset}>Create another</Button>
          </div>
          {jobId && <p className="text-[11px] text-muted-foreground">Job {jobId.slice(0, 8)} · Made by TRELLIS 2 (open source) on the Startup Factory computer</p>}
        </div>
      )}
    </div>
  );
}
